function toggleMobileNav(){const nav=document.querySelector('.mobile-nav');if(nav){nav.classList.toggle('open');}}function setTheme(theme){document.documentElement.setAttribute('data-theme',theme);localStorage.setItem('theme',theme);}function initTheme(){const savedTheme=localStorage.getItem('theme')|| 'light';setTheme(savedTheme);}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initTheme);}else{initTheme();}if(typeof module !=='undefined' && module.exports){module.exports={toggleMobileNav,setTheme,initTheme};}